SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_270
WHERE (rt.role IN ('actor','actress','cinematographer','composer','costume designer','director','editor','miscellaneous crew','producer','production designer','writer')) AND n.id = non_leaf_270.ci_person_id AND it1.id = non_leaf_270.mi1_info_type_id AND (it1.id IN ('7')) AND (pi.info ILIKE '%fran%') AND (kt.kind IN ('movie','tv mini series','tv movie','tv series','video game','video movie')) AND it2.id = non_leaf_270.pi_info_type_id AND (mi1.info ILIKE '%lett%') AND n.id = non_leaf_270.pi_person_id AND (it2.id IN ('37'));